package org.eclipse.rdf4j.sail.lmdb;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Objects;

/**
 * Splits an ordered predicate catalog into contiguous groups whose approximate statement counts are as equal as the
 * data allows (plan: paged-CSF weighted build split).
 * <p>
 * The paged CSF base build cuts each logical plane into disjoint scan ranges and lets a worker pool consume them.
 * Cutting by predicate count — or by interpolated key space, which amounts to the same thing on a predicate-leading
 * index — hands the range holding {@code rdf:type} a third of a typical dataset while its siblings idle. This planner
 * instead consumes an approximate per-predicate statement count and answers with contiguous groups plus, for a
 * predicate too large to fit one range, how many sub-ranges the caller should cut inside it.
 * <p>
 * Groups stay contiguous on purpose: a group is executed as one half-open LMDB key range, and
 * {@link org.eclipse.rdf4j.sail.lmdb.csf.ImmutablePagedQuadCsfIndex#mergeBuildPlans} requires every partition's shards
 * to arrive in ascending row order, which contiguous groups satisfy by construction.
 */
final class LmdbAdjacencyPredicateWorkSplit {

	/**
	 * A predicate-count multiple above which a single predicate is worth isolating and subdividing. A predicate between
	 * one and two ideal shares already lands alone in its own group through the packing branch, so reserving
	 * subdivision — which costs extra LMDB split-planning seeks — for genuinely oversized predicates keeps the plan
	 * cheap.
	 */
	private static final double SUBDIVIDE_THRESHOLD = 2.0;

	private LmdbAdjacencyPredicateWorkSplit() {
	}

	/**
	 * One contiguous half-open predicate group {@code [fromInclusive, toExclusive)} carrying {@code weight} approximate
	 * statements, to be cut into {@code partitions} scan ranges. Only a single-predicate group may be subdivided,
	 * because a sub-range boundary has to fall inside one predicate's key range.
	 */
	record Group(int fromInclusive, int toExclusive, int partitions, long weight) {

		Group {
			if (fromInclusive < 0 || toExclusive < fromInclusive) {
				throw new IllegalArgumentException(
						"invalid predicate group bounds: [" + fromInclusive + ", " + toExclusive + ")");
			}
			if (partitions < 1) {
				throw new IllegalArgumentException("a predicate group needs at least one partition: " + partitions);
			}
			if (weight < 0) {
				throw new IllegalArgumentException("a predicate group weight must be nonnegative: " + weight);
			}
			if (partitions > 1 && toExclusive - fromInclusive != 1) {
				throw new IllegalArgumentException("only a single-predicate group may be subdivided");
			}
		}

		int size() {
			return toExclusive - fromInclusive;
		}
	}

	/**
	 * Plans weight-balanced groups, allowing an oversized predicate to be marked for subdivision. The returned groups
	 * tile {@code [0, weights.length)} in ascending order without gaps, and their partitions sum to at most
	 * {@code max(1, targetRanges)}. A single returned group means the input carries no usable signal and the caller
	 * should keep whatever partitioning it used before.
	 */
	static Group[] plan(long[] weights, int targetRanges) {
		return plan(weights, targetRanges, true);
	}

	/**
	 * Plans weight-balanced groups for a caller that cannot cut inside one predicate, and returns the group boundaries
	 * as {@code groups + 1} ascending offsets starting at {@code 0} and ending at {@code weights.length}.
	 */
	static int[] contiguousBounds(long[] weights, int targetRanges) {
		Group[] groups = plan(weights, targetRanges, false);
		int[] bounds = new int[groups.length + 1];
		bounds[0] = groups[0].fromInclusive();
		for (int group = 0; group < groups.length; group++) {
			bounds[group + 1] = groups[group].toExclusive();
		}
		return bounds;
	}

	/**
	 * Hands out a budget of scan ranges to a fixed set of predicates in proportion to their approximate statement
	 * counts, giving every predicate at least one range.
	 * <p>
	 * This is the sibling of {@link #plan(long[], int)} for callers whose predicates are already fixed and disjoint — a
	 * SELECTED coverage, where each predicate is scanned as its own key range and the only question is how finely to
	 * subdivide each one. Shares are apportioned by largest remainder, so the returned counts sum to exactly
	 * {@code budget} whenever {@code budget >= weights.length}, and to {@code weights.length} otherwise.
	 */
	static int[] apportionPartitions(long[] weights, int budget) {
		Objects.requireNonNull(weights, "weights");
		int predicateCount = weights.length;
		int[] partitions = new int[predicateCount];
		Arrays.fill(partitions, 1);
		if (predicateCount == 0 || budget <= predicateCount) {
			return partitions;
		}
		long total = 0;
		for (long weight : weights) {
			if (weight < 0) {
				throw new IllegalArgumentException("predicate weights must be nonnegative: " + weight);
			}
			total = Math.addExact(total, weight);
		}
		int assigned = predicateCount;
		double[] remainders = new double[predicateCount];
		if (total > 0) {
			for (int predicate = 0; predicate < predicateCount && assigned < budget; predicate++) {
				double share = (double) weights[predicate] * budget / total;
				int wholeShares = (int) Math.floor(share);
				// The predicate already holds one range, so only the shares beyond the first are still owed.
				int extra = Math.max(0, Math.min(wholeShares - 1, budget - assigned));
				partitions[predicate] += extra;
				assigned += extra;
				remainders[predicate] = share - wholeShares;
			}
		}
		Integer[] byRemainder = new Integer[predicateCount];
		for (int predicate = 0; predicate < predicateCount; predicate++) {
			byRemainder[predicate] = predicate;
		}
		Arrays.sort(byRemainder, (left, right) -> Double.compare(remainders[right], remainders[left]));
		for (int i = 0; i < byRemainder.length && assigned < budget; i++) {
			partitions[byRemainder[i]]++;
			assigned++;
		}
		if (assigned < budget) {
			// Whatever the largest-remainder round could not place goes to the predicate that will take longest.
			int heaviest = 0;
			for (int predicate = 1; predicate < predicateCount; predicate++) {
				if (weights[predicate] > weights[heaviest]) {
					heaviest = predicate;
				}
			}
			partitions[heaviest] += budget - assigned;
		}
		return partitions;
	}

	private static Group[] plan(long[] weights, int targetRanges, boolean allowSubdivision) {
		Objects.requireNonNull(weights, "weights");
		int predicateCount = weights.length;
		if (predicateCount == 0) {
			return new Group[] { new Group(0, 0, 1, 0) };
		}
		long total = 0;
		for (long weight : weights) {
			if (weight < 0) {
				throw new IllegalArgumentException("predicate weights must be nonnegative: " + weight);
			}
			total = Math.addExact(total, weight);
		}
		if (targetRanges <= 1 || total == 0) {
			return new Group[] { new Group(0, predicateCount, 1, total) };
		}

		List<Group> groups = new ArrayList<>(Math.min(predicateCount, targetRanges) + 1);
		long remainingWeight = total;
		int remainingRanges = targetRanges;
		int predicate = 0;
		while (predicate < predicateCount && remainingRanges > 0) {
			if (remainingRanges == 1) {
				groups.add(new Group(predicate, predicateCount, 1, remainingWeight));
				predicate = predicateCount;
				break;
			}
			// The ideal weight of the next range is re-derived every step so that rounding losses of earlier groups
			// are absorbed by the groups that follow instead of accumulating into the tail.
			double ideal = (double) remainingWeight / remainingRanges;
			long weight = weights[predicate];
			if (allowSubdivision && ideal > 0 && weight >= SUBDIVIDE_THRESHOLD * ideal) {
				// Keep one range for the tail so the remaining predicates are never squeezed into nothing.
				int budget = predicate + 1 < predicateCount ? remainingRanges - 1 : remainingRanges;
				int partitions = (int) Math.max(1L, Math.min(budget, Math.round(weight / ideal)));
				groups.add(new Group(predicate, predicate + 1, partitions, weight));
				remainingRanges -= partitions;
				remainingWeight -= weight;
				predicate++;
				continue;
			}
			int start = predicate;
			long accumulated = 0;
			// Always consume at least one predicate, otherwise an all-zero tail would not make progress. Stop before
			// a predicate that already fills a range on its own: packing it here would hide it inside a group and
			// deny it the isolation (and, above the subdivision threshold, the sub-ranges) it needs.
			do {
				accumulated += weights[predicate];
				predicate++;
			} while (predicate < predicateCount && accumulated < ideal && weights[predicate] < ideal);
			groups.add(new Group(start, predicate, 1, accumulated));
			remainingRanges--;
			remainingWeight -= accumulated;
		}
		if (predicate < predicateCount) {
			// Defensive: the loop always reserves a range for the tail, so this is unreachable. Should the budget
			// arithmetic ever change, absorb the tail rather than silently dropping predicates from the plan.
			Group last = groups.get(groups.size() - 1);
			long weight = 0;
			for (int tail = predicate; tail < predicateCount; tail++) {
				weight = Math.addExact(weight, weights[tail]);
			}
			if (last.partitions() == 1) {
				groups.set(groups.size() - 1, new Group(last.fromInclusive(), predicateCount, 1,
						Math.addExact(last.weight(), weight)));
			} else {
				groups.add(new Group(predicate, predicateCount, 1, weight));
			}
		}
		return groups.toArray(Group[]::new);
	}
}
